`timescale 1ns/1ps

// Synchronous BRAM-backed parameter stores. INIT_* files are generated by
// scripts/export_camus_pl_rom.py and added as memory files by the Vivado flow.
module camus_stream_parameter_rom #(
    parameter integer WEIGHT_WORDS = 2048,
    parameter integer PARAMETER_GROUPS = 64,
    parameter integer SIMD = 8,
    parameter WEIGHT_INIT = "weights_pe4s8.mem",
    parameter BIAS_INIT = "bias_pe4.mem",
    parameter MULT_INIT = "multiplier_pe4.mem",
    parameter SHIFT_INIT = "shift_pe4.mem"
) (
    input  logic clk,
    input  logic [$clog2(WEIGHT_WORDS)-1:0] weight_address,
    output logic [4*SIMD*4-1:0] weight_word,
    input  logic [$clog2(PARAMETER_GROUPS)-1:0] parameter_address,
    output logic signed [127:0] bias_word,
    output logic signed [127:0] multiplier_word,
    output logic signed [27:0] shift_word
);
    (* rom_style = "block" *) logic [127:0] weight_memory [0:WEIGHT_WORDS-1];
    (* rom_style = "block" *) logic [127:0] bias_memory [0:PARAMETER_GROUPS-1];
    (* rom_style = "block" *) logic [127:0] multiplier_memory [0:PARAMETER_GROUPS-1];
    (* rom_style = "block" *) logic [27:0] shift_memory [0:PARAMETER_GROUPS-1];
    logic [127:0] weight_lo, weight_hi;
    wire [$clog2(WEIGHT_WORDS)-1:0] next_weight_address = weight_address + 1'b1;

    initial begin
        $readmemh(WEIGHT_INIT, weight_memory);
        $readmemh(BIAS_INIT, bias_memory);
        $readmemh(MULT_INIT, multiplier_memory);
        $readmemh(SHIFT_INIT, shift_memory);
    end

    generate if (SIMD == 16) begin : g_pair
        always_ff @(posedge clk) begin
            weight_lo <= weight_memory[weight_address];
            weight_hi <= weight_memory[next_weight_address];
        end
        for (genvar p = 0; p < 4; p = p + 1) begin : g_pe
            assign weight_word[p*64 +: 64] = {weight_hi[p*32 +: 32], weight_lo[p*32 +: 32]};
        end
    end else begin : g_single
        always_ff @(posedge clk)
            weight_word <= weight_memory[weight_address];
    end endgenerate
    always_ff @(posedge clk) begin
        bias_word <= bias_memory[parameter_address];
        multiplier_word <= multiplier_memory[parameter_address];
        shift_word <= shift_memory[parameter_address];
    end
endmodule
